import React, { useState, useEffect } from 'react';
import { getStore1AllStocks, createStore1Stock, updateStore1Stock } from '../../services/stockService';

const StockOperations = () => {
    const [stocks, setStocks] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [selectedStock, setSelectedStock] = useState(null);

    const [stockForm, setStockForm] = useState({
        productCode: '',
        category: '',
        productName: '',
        size: '',
        color: '',
        quantity: 0,
        unitPrice: 0
    });

    useEffect(() => {
        fetchStocks();
    }, []);

    const fetchStocks = async () => {
        try {
            setLoading(true);
            setError(null);
            const response = await getStore1AllStocks();

            if (!response || !response.success) {
                throw new Error(response?.message || 'Stok verisi alınamadı');
            }

            // API'den gelen store1Stocks array'ini kullan
            setStocks(response.store1Stocks || []);
        } catch (err) {
            console.error('Stok verisi yüklenirken hata:', err);
            setError(err.message || 'Stok verileri yüklenirken bir hata oluştu');
            setStocks([]);
        } finally {
            setLoading(false);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const response = await createStore1Stock(stockForm);
            if (response.success) {
                setStockForm({
                    productCode: '',
                    category: '',
                    productName: '',
                    size: '',
                    color: '',
                    quantity: 0,
                    unitPrice: 0
                });
                fetchStocks();
            } else {
                setError(response.message);
            }
        } catch (err) {
            setError('Stok oluşturulurken bir hata oluştu');
        }
    };

    const handleUpdate = async (e) => {
        e.preventDefault();
        if (!selectedStock) return;

        try {
            const response = await updateStore1Stock(selectedStock);
            if (response.success) {
                setSelectedStock(null);
                fetchStocks();
            } else {
                setError(response.message);
            }
        } catch (err) {
            setError('Stok güncellenirken bir hata oluştu');
        }
    };

    if (loading) return (
        <div className="flex justify-center items-center h-full">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-gray-900"></div>
        </div>
    );

    if (error) return (
        <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative" role="alert">
            <strong className="font-bold">Hata!</strong>
            <span className="block sm:inline"> {error}</span>
        </div>
    );

    return (
        <div className="space-y-6">
            {/* Stok Ekleme Formu */}
            <div className="bg-white rounded-lg shadow-md p-6">
                <h2 className="text-xl font-bold mb-4">Yeni Stok Ekle</h2>
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700">Ürün Kodu</label>
                            <input
                                type="text"
                                value={stockForm.productCode}
                                onChange={(e) => setStockForm({...stockForm, productCode: e.target.value})}
                                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                                required
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700">Kategori</label>
                            <input
                                type="text"
                                value={stockForm.category}
                                onChange={(e) => setStockForm({...stockForm, category: e.target.value})}
                                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                                required
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700">Ürün Adı</label>
                            <input
                                type="text"
                                value={stockForm.productName}
                                onChange={(e) => setStockForm({...stockForm, productName: e.target.value})}
                                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                                required
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700">Beden</label>
                            <input
                                type="text"
                                value={stockForm.size}
                                onChange={(e) => setStockForm({...stockForm, size: e.target.value})}
                                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                                required
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700">Renk</label>
                            <input
                                type="text"
                                value={stockForm.color}
                                onChange={(e) => setStockForm({...stockForm, color: e.target.value})}
                                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                                required
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700">Miktar</label>
                            <input
                                type="number"
                                value={stockForm.quantity}
                                onChange={(e) => setStockForm({...stockForm, quantity: parseInt(e.target.value)})}
                                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                                required
                                min="0"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700">Birim Fiyat</label>
                            <input
                                type="number"
                                value={stockForm.unitPrice}
                                onChange={(e) => setStockForm({...stockForm, unitPrice: parseFloat(e.target.value)})}
                                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                                required
                                min="0"
                                step="0.01"
                            />
                        </div>
                    </div>
                    <div className="flex justify-end">
                        <button
                            type="submit"
                            className="inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
                        >
                            Stok Ekle
                        </button>
                    </div>
                </form>
            </div>

            {/* Stok Listesi */}
            <div className="bg-white rounded-lg shadow-md p-6">
                <h2 className="text-xl font-bold mb-4">Stok Listesi</h2>
                {stocks.length === 0 ? (
                    <div className="text-center text-gray-500 py-4">
                        Henüz stok kaydı bulunmamaktadır.
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="min-w-full divide-y divide-gray-200">
                            <thead className="bg-gray-50">
                                <tr>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Ürün Kodu
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Kategori
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Ürün Adı
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Beden
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Renk
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Miktar
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        Birim Fiyat
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                        İşlemler
                                    </th>
                                </tr>
                            </thead>
                            <tbody className="bg-white divide-y divide-gray-200">
                                {stocks.map((stock) => (
                                    <tr key={stock.id} className="hover:bg-gray-50">
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {stock.productCode}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {stock.category}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {stock.productName}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {stock.size}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {stock.color}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {stock.quantity}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                            {new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' })
                                                .format(stock.unitPrice)}
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                                            <button
                                                onClick={() => setSelectedStock(stock)}
                                                className="text-indigo-600 hover:text-indigo-900 mr-4"
                                            >
                                                Düzenle
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            {/* Stok Güncelleme Modal */}
            {selectedStock && (
                <div className="fixed inset-0 bg-gray-600 bg-opacity-50 overflow-y-auto h-full w-full">
                    <div className="relative top-20 mx-auto p-5 border w-96 shadow-lg rounded-md bg-white">
                        <div className="mt-3">
                            <h3 className="text-lg font-medium leading-6 text-gray-900">Stok Güncelle</h3>
                            <form onSubmit={handleUpdate} className="mt-4">
                                <div className="mb-4">
                                    <label className="block text-sm font-medium text-gray-700">Miktar</label>
                                    <input
                                        type="number"
                                        value={selectedStock.quantity}
                                        onChange={(e) => setSelectedStock({
                                            ...selectedStock,
                                            quantity: parseInt(e.target.value)
                                        })}
                                        className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                                        min="0"
                                        required
                                    />
                                </div>
                                <div className="mb-4">
                                    <label className="block text-sm font-medium text-gray-700">Birim Fiyat</label>
                                    <input
                                        type="number"
                                        value={selectedStock.unitPrice}
                                        onChange={(e) => setSelectedStock({
                                            ...selectedStock,
                                            unitPrice: parseFloat(e.target.value)
                                        })}
                                        className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm"
                                        min="0"
                                        step="0.01"
                                        required
                                    />
                                </div>
                                <div className="flex justify-end space-x-3">
                                    <button
                                        type="button"
                                        onClick={() => setSelectedStock(null)}
                                        className="inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-gray-700 bg-gray-100 hover:bg-gray-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-500"
                                    >
                                        İptal
                                    </button>
                                    <button
                                        type="submit"
                                        className="inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
                                    >
                                        Güncelle
                                    </button>
                                </div>
                            </form>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default StockOperations;
